* { box-sizing: border-box; }
.task-card {
  width: 320px;
  padding: 16px;
  border: 1px solid;
  margin-block: 12px;
}

.task-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.task-toolbar .search { flex: 1 1 240px; }

.button:hover { filter: brightness(1.08); }
.button:focus-visible { outline: 3px solid currentColor; outline-offset: 3px; }
.button:disabled { opacity: .55; cursor: not-allowed; }
.field[aria-invalid="true"] { border-color: #ff7a7a; }
